const token = $node['Read SA Token'].json.stdout.trim();
const base = 'https://kubernetes.default.svc';
const deploymentPath = '/apis/apps/v1/namespaces/omp/deployments/omp-backend-developer';
const headers = { Authorization: `Bearer ${token}` };
const kube = (method, path, body, contentType) => this.helpers.httpRequest({ method, url: `${base}${path}`, headers: { ...headers, ...(contentType ? { 'Content-Type': contentType } : {}) }, ...(body === undefined ? {} : { body, json: true }), skipSslCertificateValidation: true, timeout: 15000 });
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
const report = { role: 'backend-developer', kaneo_identity: 'role api key (backend-developer)' };
let originalReplicas = 0;
let patched = false;
let result;
try {
  const before = await kube('GET', deploymentPath);
  originalReplicas = before.spec.replicas ?? 0;
  const containerIndex = before.spec.template.spec.containers.findIndex(c => c.name === 'omp');
  if (containerIndex < 0) throw new Error('omp container missing from deployment');
  const envPath = `/spec/template/spec/containers/${containerIndex}/env`;
  const env = before.spec.template.spec.containers[containerIndex].env || [];
  if (env.some(e => ['KANEO_API_KEY'].includes(e.name))) throw new Error('probe env already exists; refusing to overwrite it');
  const probeEnv = [
    { name: 'KANEO_API_KEY', valueFrom: { secretKeyRef: { name: 'kaneo-authentik-probe', key: 'api_key' } } }
  ];
  const ops = [{ op: 'add', path: '/spec/replicas', value: 1 }];
  if (before.spec.template.spec.containers[containerIndex].env) {
    for (const item of probeEnv) ops.push({ op: 'add', path: `${envPath}/-`, value: item });
  } else {
    ops.push({ op: 'add', path: envPath, value: probeEnv });
  }
  patched = true;
  await kube('PATCH', deploymentPath, ops, 'application/json-patch+json');

  const deadline = Date.now() + 180000;
  let ready = false;
  while (Date.now() < deadline) {
    const current = await kube('GET', deploymentPath);
    if ((current.status?.availableReplicas || 0) > 0) { ready = true; break; }
    await sleep(5000);
  }
  if (!ready) throw new Error('backend-developer pod did not become ready within 180 seconds');

  let health;
  const healthDeadline = Date.now() + 60000;
  while (Date.now() < healthDeadline) {
    try {
      health = await this.helpers.httpRequest({ method: 'GET', url: 'http://omp-backend-developer.omp.svc:4096/healthz', json: true, timeout: 5000 });
      if (health.status === 'ok') break;
    } catch (e) { health = undefined; }
    await sleep(2000);
  }
  if (!health || health.status !== 'ok') throw new Error('backend-developer health endpoint did not report ok within 60 seconds');
  const prompt = `Kaneo is reachable in-cluster at http://kaneo.kaneo.svc.cluster.local:5173. KANEO_API_KEY (from this process environment) is the backend-developer SDLC role's real, pre-minted Kaneo API key — minted by role-accounts.yml by signing in as the Kaneo admin, impersonating this role's account, and calling api-key/create under that impersonated session (NOT a password or OIDC login; this role's Kaneo account has no password at all by design). Role accounts cannot sign in directly — do NOT attempt /api/auth/sign-in/email, /api/auth/sign-in/social, or any Authentik/OIDC redirect; all of those are wrong for this identity. Authenticate instead by calling GET http://kaneo.kaneo.svc.cluster.local:5173/api/workspace with header Authorization: Bearer KANEO_API_KEY. A 200 response (even an empty or non-empty workspace list) confirms this role's API key authenticates correctly against Kaneo's REST API; a 401/403 means the key is rejected. Do not print, echo, log, or reveal the key value, or any full response body. Do not dump the environment. Do not create, read, or modify tickets. Use only in-cluster URLs and non-interactive HTTP tools; no browser. Return JSON only: {"http_status":200,"authenticated":true,"failure_class":null} on success; otherwise report actual numeric http_status, authenticated false, and sanitized failure_class. Never claim an unobserved status. Never include secret values.`;
  const completion = await this.helpers.httpRequest({ method: 'POST', url: 'http://omp-backend-developer.omp.svc:4096/v1/chat/completions', body: { model: 'omp-backend-developer', messages: [{ role: 'user', content: prompt }], stream: false }, json: true, timeout: 600000 });
  const text = completion.choices?.[0]?.message?.content || '(no probe result returned)';
  result = { ...report, health: health.status, probe: text.replace(/\b[0-9a-f]{64}\b/gi, '[redacted]') };
} catch (error) {
  result = { ...report, error: String(error.message || error).replace(/\b[0-9a-f]{64}\b/gi, '[redacted]') };
} finally {
  if (patched) {
    try {
      const current = await kube('GET', deploymentPath);
      const containerIndex = current.spec.template.spec.containers.findIndex(c => c.name === 'omp');
      const env = current.spec.template.spec.containers[containerIndex].env || [];
      const indexes = env.map((e, i) => ['KANEO_API_KEY'].includes(e.name) ? i : -1).filter(i => i >= 0).sort((a, b) => b - a);
      const ops = [{ op: 'replace', path: '/spec/replicas', value: originalReplicas }];
      for (const i of indexes) ops.push({ op: 'remove', path: `/spec/template/spec/containers/${containerIndex}/env/${i}` });
      await kube('PATCH', deploymentPath, ops, 'application/json-patch+json');
      result.cleanup = 'deployment restored';
    } catch (error) {
      result.cleanup = `manual cleanup required: ${String(error.message || error).replace(/\b[0-9a-f]{64}\b/gi, '[redacted]')}`;
    }
  }
  try {
    await kube('DELETE', '/api/v1/namespaces/omp/secrets/kaneo-authentik-probe');
    result.secret = 'temporary credential deleted';
  } catch (error) {
    result.secret = `manual secret cleanup required: ${String(error.message || error).replace(/\b[0-9a-f]{64}\b/gi, '[redacted]')}`;
  }
}
let probeReport = {}; try { probeReport = JSON.parse(result.probe || ''); } catch {}
const probeOk = probeReport.http_status === 200 && probeReport.authenticated === true;
const cleanupOk = (!patched || result.cleanup === 'deployment restored') && result.secret === 'temporary credential deleted';
return [{ json: { ...result, probeReport, succeeded: probeOk && cleanupOk, failed: !(probeOk && cleanupOk) } }];
